Lemma u32arr_app_zeros : forall m A ws k,
  u32arr asegs m A ws ->
  rw_cells asegs m (A + 4 * Z.of_nat (length ws)) [CB (4 * k)%nat (repeat (Z_to_bv 8 0) (4 * k))] ->
